// Verify the committed engine lock describes the sources in the working tree.
//
// `engine/shared-engine.lock.json` is the record of the engine revision an APK
// was built from. It is regenerated by prepare-shared-engine.mjs, so a mismatch
// means a source change was not committed together with its lock.
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

const read = async file => readFile(path.join(root, file), 'utf8').catch(error => {
  if (error.code === 'ENOENT') {
    throw new Error(`Missing ${file}. Run node scripts/prepare-shared-engine.mjs and commit the result.`);
  }
  throw error;
});

const committed = await read('engine/shared-engine.lock.json');
const staged = await read('engine/build/assets/shared-engine/lock.json');

if (committed !== staged) {
  const before = JSON.parse(committed);
  const after = JSON.parse(staged);
  const changed = Object.keys(after).filter(key => before[key] !== after[key]);
  throw new Error(
    `engine/shared-engine.lock.json is stale (${changed.join(', ')}).\n`
    + 'Run node scripts/prepare-shared-engine.mjs and commit the regenerated lock with this change.',
  );
}

const lock = JSON.parse(committed);
console.log(`Engine lock matches the staged sources (converter ${lock.converterRevision}, swift ${lock.swiftSources.slice(0, 12)}).`);
